// ===========================================================================
// All Constructions Summary Test
// ===========================================================================

#[test]
fn test_fd_solver_all_constructions_summary() {
    let constructions = vec![
        ("200mm Concrete", concrete_200mm_spec(), "fixed_zone_20c"),
        ("Lightweight Wall", lightweight_wall_spec(), "lightweight"),
        ("Composite Wall", composite_wall_spec(), "composite"),
        ("Roof", roof_spec(), "roof"),
        ("Floor (Ground)", floor_spec(), "floor"),
    ];

    let mut results = Vec::new();

    for (name, spec, ref_name) in &constructions {
        let ref_data = load_reference_data(ref_name);
        let result = test_fd_construction_dirichlet(spec, &ref_data, name);
        results.push(result);
    }

    eprintln!("\n========================================");
    eprintln!("FD Solver Per-Construction Summary");
    eprintln!("========================================");
    eprintln!(
        "{:<20} {:>10} {:>12} {:>12} {:>8}",
        "Construction", "Max Abs Err", "Max Rel Err", "Failed Rows", "Status"
    );
    eprintln!("----------------------------------------");

    for result in &results {
        eprintln!(
            "{:<20} {:>10.4} {:>11.2}% {:>12} {:>8}",
            result.name,
            result.max_absolute_error,
            result.max_relative_error * 100.0,
            format!("{}/{}", result.failed_rows, result.total_rows),
            if result.passed { "PASS" } else { "FAIL" }
        );
    }

    eprintln!("========================================\n");

    let all_passed = results.iter().all(|r| r.passed);
    assert!(
        all_passed,
        "Some construction types failed FD solver validation"
    );
}

// ===========================================================================
// Performance Test
// ===========================================================================

#[test]
fn test_fd_solver_performance_8760_steps() {
    let spec = concrete_200mm_spec();
    let fd_layers: Vec<MaterialLayer> = spec.to_fd_material_layers();
    let disc = fluxion::physics::fd_discretization::WallDiscretization::from_layers(&fd_layers, 20);
    let mut solver = ImplicitFDSolver::new(disc, 20.0);

    let start = std::time::Instant::now();
    for i in 0..8760 {
        let hour = (i % 24) as f64;
        let t_ext = 10.0 + 10.0 * ((hour - 6.0) * std::f64::consts::PI / 12.0).sin();
        let interior_bc = SurfaceBC::new_interior(H_INTERIOR, 20.0);
        let exterior_bc = SurfaceBC::new_exterior(H_EXTERIOR, t_ext, 0.0);
        solver.step(3600.0, &interior_bc, &exterior_bc);
    }
    let elapsed = start.elapsed();

    eprintln!(
        "\nFD solver: 8760 steps in {:.2} ms",
        elapsed.as_secs_f64() * 1000.0
    );
    assert!(
        elapsed.as_secs() < 2,
        "FD solver should complete 8760 steps in < 2s, took {:.2}s",
        elapsed.as_secs_f64()
    );
}

// ===========================================================================
// WallSpec Verification Tests
// ===========================================================================

#[test]
fn test_wall_spec_concrete_200mm() {
    let spec = concrete_200mm_spec();
    let expected_capacity = 2243.0 * 837.0 * 0.2;
    assert!(
        (spec.thermal_capacity() - expected_capacity).abs() < 1.0,
        "Thermal capacity mismatch: got {:.1}, expected {:.1}",
        spec.thermal_capacity(),
        expected_capacity
    );
    let expected_r = 0.2 / 1.73;
    assert!(
        (spec.total_r_value() - expected_r).abs() < 1e-10,
        "R-value mismatch"
    );
}

#[test]
fn test_wall_spec_lightweight() {
    let spec = lightweight_wall_spec();
    assert_eq!(spec.layers.len(), 3);
    assert!(
        spec.total_r_value() > 1.0,
        "Lightweight wall should have R > 1.0 m²K/W"
    );
    assert!(
        spec.thermal_capacity() < 50_000.0,
        "Lightweight wall should have C < 50 kJ/m²K"
    );
}

#[test]
fn test_wall_spec_composite() {
    let spec = composite_wall_spec();
    assert_eq!(spec.layers.len(), 3);
    assert!(
        spec.total_r_value() > 0.5,
        "Composite wall should have R > 0.5 m²K/W"
    );
    assert!(
        spec.thermal_capacity() > 100_000.0,
        "Composite wall should have C > 100 kJ/m²K"
    );
}

#[test]
fn test_wall_spec_roof() {
    let spec = roof_spec();
    assert_eq!(spec.layers.len(), 3);
    assert!(spec.total_r_value() > 1.0, "Roof should have R > 1.0 m²K/W");
}

#[test]
fn test_wall_spec_floor() {
    let spec = floor_spec();
    assert_eq!(spec.layers.len(), 2);
    assert!(
        spec.total_r_value() > 1.0,
        "Floor should have R > 1.0 m²K/W"
    );
}
